mapper.select:
SELECT q.course_question_no AS courseQuestionNo, q.course_no AS courseNo, q.course_question_title AS courseQuestionTitle, q.course_question_status AS courseQuestionStatus, q.createdate AS createdate, u.user_name AS writerName,
(SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END FROM tb_course_question_answer qa WHERE qa.course_question_no = q.course_question_no ) AS answered
FROM tb_course_question q LEFT JOIN tb_sysuser u ON q.writer_user_no = u.user_no WHERE q.course_no = #{courseNo} ORDER BY q.createdate DESC LIMIT #{startRow}, #{rowPerPage}

mapper.update:
UPDATE tb_course_question_answer
SET answer_content = #{answerContent}
WHERE answer_no = #{answerNo}
